#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────


REPO="firatciftci/segue"
ENVIRONMENT="release"
TEAM_ID="55PN4MC8Q6"
IDENTITY="Developer ID Application: Firat Ciftci ($TEAM_ID)"
P12="$HOME/Desktop/SegueDeveloperID.p12"
SPARKLE_BIN="$(cd "$(dirname "$0")/.." && pwd)/build/check/SourcePackages/artifacts/sparkle/Sparkle/bin"
SPARKLE_ACCOUNT="segue"
WORK=$(mktemp -d)
trap 'rm -rf "$WORK"; rm -f "$P12"' EXIT

set_env_secret() {
  local name="$1"
  if gh secret set "$name" --env "$ENVIRONMENT" --repo "$REPO" >/dev/null 2>&1; then
    WRITTEN_SECRET+=("$name")
    printf '  %s✓ set%s %s\n' "$GREEN" "$RESET" "$name"
  else
    SKIPPED+=("$name: gh secret set $name --env $ENVIRONMENT --repo $REPO")
    warn "couldn't set $name"
  fi
}

fail() { printf '  %s✗ %s%s\n' "$RED" "$1" "$RESET"; }
ok() { printf '  %s✓ %s%s\n' "$GREEN" "$1" "$RESET"; }

newest() {
  local pattern="$1" found=""
  for candidate in $pattern; do
    [[ -f "$candidate" ]] || continue
    if [[ -z "$found" || "$candidate" -nt "$found" ]]; then found="$candidate"; fi
  done
  printf '%s' "$found"
}

ask_path() {
  local key="$1" prompt="$2" default="$3" input
  if [[ -n "$default" ]]; then
    printf '  %s%s%s %s[Enter for %s]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "${default/#$HOME/~}" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  input="${input:-$default}"
  input="${input/#\~/$HOME}"
  printf -v "$key" '%s' "$input"
}

TOTAL_STAGES=5

banner "Segue release secrets"

stage "GitHub access"
say "Six secrets go into the $ENVIRONMENT environment of $REPO."
say "Only builds of v* tags can read them."
until gh auth status >/dev/null 2>&1; do
  warn "The GitHub CLI isn't signed in."
  step "In another terminal, run: gh auth login"
  pause "Press Enter once you're signed in"
done
if ! gh api "repos/$REPO/environments/$ENVIRONMENT" >/dev/null 2>&1; then
  fail "Couldn't find the $ENVIRONMENT environment on $REPO. Check that you have admin access."
  exit 1
fi
current=$(gh secret list --env "$ENVIRONMENT" --repo "$REPO" --json name --jq '[.[].name] | join(", ")' 2>/dev/null || true)
ok "Signed in, and the $ENVIRONMENT environment exists."
note "Already set: ${current:-none}. Setting a secret again replaces it."
pause "Press Enter to start with the certificate"

stage "Developer ID certificate"
say "Export your Developer ID certificate with its private key as a .p12 file."
note "The wizard deletes the file from your Desktop once it's uploaded."
open -a "Keychain Access"
step "In Keychain Access, choose login in the sidebar, then the My Certificates tab."
step "Find \"$IDENTITY\"."
step "Select it, choose File > Export Items…, and save it to your Desktop as SegueDeveloperID.p12 in .p12 format."
step "Pick a password when asked, then enter your Mac password to allow the export."
until [[ -f "$P12" ]]; do
  pause "Press Enter once SegueDeveloperID.p12 is on your Desktop"
  [[ -f "$P12" ]] || warn "Not found at ${P12/#$HOME/~} yet."
done
check_keychain="$WORK/check.keychain-db"
while true; do
  ask_secret P12_PASSWORD "Password you chose for the .p12:"
  security delete-keychain "$check_keychain" >/dev/null 2>&1 || true
  security create-keychain -p check "$check_keychain" >/dev/null 2>&1
  if security import "$P12" -k "$check_keychain" -P "$P12_PASSWORD" >/dev/null 2>&1 \
    && [[ "$(security find-identity -p codesigning "$check_keychain" 2>/dev/null)" == *"Developer ID Application"* ]]; then
    ok "The file opens and holds your Developer ID identity."
    break
  fi
  fail "That password didn't open the file, or it has no Developer ID private key. Try the password again."
done
security delete-keychain "$check_keychain" >/dev/null 2>&1 || true
set_env_secret DEVELOPER_ID_CERTIFICATE < <(base64 -i "$P12")
set_env_secret DEVELOPER_ID_CERTIFICATE_PASSWORD < <(printf '%s' "$P12_PASSWORD")
unset P12_PASSWORD
rm -f "$P12"
ok "Deleted SegueDeveloperID.p12 from your Desktop."
pause

stage "App Store Connect API key"
say "Notarization uses an App Store Connect API key."
note "If you already made one for another app, you can reuse its .p8 file."
open_url "https://appstoreconnect.apple.com/access/integrations/api"
step "Open the Team Keys tab. If it's your first key, click Request Access and accept the terms."
step "Click Generate API Key. Name it Segue notarization, set Access to Developer, then click Generate."
step "Click Download on the new key. Apple only lets you download it once."
while true; do
  ask NOTARY_KEY_ID "Key ID (in the row for the key):"
  ask NOTARY_ISSUER_ID "Issuer ID (shown above the keys table):"
  ask_path NOTARY_KEY_PATH "Path to the .p8 key:" "$(newest "$HOME/Downloads/AuthKey_*.p8 $HOME/.appstoreconnect/private_keys/AuthKey_*.p8")"
  if [[ ! -f "$NOTARY_KEY_PATH" ]]; then
    fail "No file at $NOTARY_KEY_PATH."
    continue
  fi
  note "Checking the key with Apple's notary service…"
  if xcrun notarytool history --key "$NOTARY_KEY_PATH" --key-id "$NOTARY_KEY_ID" --issuer "$NOTARY_ISSUER_ID" >/dev/null 2>&1; then
    ok "Apple accepted the key."
    break
  fi
  fail "Apple rejected these details. Check the Key ID, the Issuer ID, and that the file matches the key."
done
set_env_secret NOTARY_KEY < "$NOTARY_KEY_PATH"
set_env_secret NOTARY_KEY_ID < <(printf '%s' "$NOTARY_KEY_ID")
set_env_secret NOTARY_ISSUER_ID < <(printf '%s' "$NOTARY_ISSUER_ID")
keep="$HOME/.appstoreconnect/private_keys"
if [[ "$NOTARY_KEY_PATH" != "$keep/"* ]] && confirm "Move the .p8 key to ${keep/#$HOME/~} so you keep a copy outside Downloads?"; then
  mkdir -p "$keep"
  chmod 700 "$keep"
  mv "$NOTARY_KEY_PATH" "$keep/"
  ok "Moved it to ${keep/#$HOME/~}."
fi
pause

stage "Sparkle update key"
say "Segue checks each update against the public key in project.yml."
say "The release workflow signs updates with the matching private key from your login keychain."
until [[ -x "$SPARKLE_BIN/generate_keys" ]]; do
  warn "Sparkle's tools aren't downloaded yet."
  step "In another terminal, run: tools/check.sh"
  pause "Press Enter once it finishes"
done
expected=$(sed -nE 's/^ *SPARKLE_PUBLIC_KEY: "?([^"]+)"?$/\1/p' "$(dirname "$0")/../project.yml")
actual=$("$SPARKLE_BIN/generate_keys" --account "$SPARKLE_ACCOUNT" -p 2>/dev/null || true)
if [[ -z "$actual" ]]; then
  fail "There's no Sparkle key named $SPARKLE_ACCOUNT in your login keychain."
  exit 1
fi
if [[ "$actual" != "$expected" ]]; then
  fail "The key in your keychain doesn't match SPARKLE_PUBLIC_KEY in project.yml."
  exit 1
fi
ok "The keychain key matches project.yml."
note "macOS may ask to let generate_keys read the key. Click Allow."
"$SPARKLE_BIN/generate_keys" --account "$SPARKLE_ACCOUNT" -x "$WORK/sparkle.key" >/dev/null
set_env_secret SPARKLE_PRIVATE_KEY < "$WORK/sparkle.key"
rm -f "$WORK/sparkle.key"
warn "Keep a backup of this key. Without it, installed copies of Segue can't accept new updates."
note "Export one with: $SPARKLE_BIN/generate_keys --account $SPARKLE_ACCOUNT -x <file>"
pause

stage "Check"
names=$(gh secret list --env "$ENVIRONMENT" --repo "$REPO" --json name --jq '.[].name' 2>/dev/null || true)
missing=()
for name in DEVELOPER_ID_CERTIFICATE DEVELOPER_ID_CERTIFICATE_PASSWORD NOTARY_KEY NOTARY_KEY_ID NOTARY_ISSUER_ID SPARKLE_PRIVATE_KEY; do
  if [[ $'\n'"$names"$'\n' == *$'\n'"$name"$'\n'* ]]; then ok "$name"; else fail "$name is missing"; missing+=("$name"); fi
done
if (( ${#missing[@]} )); then
  warn "Run the wizard again to set the missing secrets."
else
  say ""
  say "Ready to release. Raise MARKETING_VERSION in project.yml if needed, merge it, then:"
  say "  git tag v1.0.0 && git push origin v1.0.0"
fi
pause "Press Enter to finish"

finish
